import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type BookingHeroProps = {
  heading: string;
  text?: string;
  button: string;
  buttonHref: string;
  photo: string;
  photoAlt: string;
  wzId?: string;
};

function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 14 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.07, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function BookingHero({ heading, text, button, buttonHref, photo, photoAlt, wzId }: BookingHeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(heading);

  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-16">
          <div className="min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {heading}
            </m.h1>
            {text ? (
              <m.p {...enter(1)} className="mt-6 max-w-text text-lead text-muted-foreground">
                {text}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-9">
              <a
                href={buttonHref}
                data-testid="wz-hero-primary"
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-7 text-center text-body font-bold text-primary-foreground transition-all duration-200 hover:-translate-y-0.5 hover:shadow-lg hover:shadow-scrim/10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {button}
              </a>
            </m.div>
          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={photo}
              srcSet={srcSetOf(photo)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={photoAlt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

