import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

// How it works: a dense band after the airy hero — three steps in one row on desktop,
// stacked on phone. The step number is drawn by the code, sitting on the same line as
// the step title (flex items-baseline), with the text under it sharing the same indent.
type Step = {
  title: string;
  text: string;
};

export type HowItWorksProps = {
  heading: string;
  steps: Step[];
};

export default function HowItWorks({ heading, steps }: HowItWorksProps) {
  const reduced = useReducedMotion();
  const rise = reduced
    ? {}
    : {
        initial: { opacity: 0, y: 16 },
        whileInView: { opacity: 1, y: 0 },
        viewport: { once: true, amount: 0.3 },
        transition: { duration: 0.5, ease: "easeOut" as const },
      };

  return (
    <section className="bg-muted font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
        <ol className="mt-10 grid gap-x-10 gap-y-8 border-t-2 border-foreground pt-8 md:grid-cols-3 md:gap-y-0">
          {steps.map((step, i) => (
            <m.li
              key={step.title}
              {...rise}
              transition={{
                ...(reduced ? {} : { duration: 0.5, ease: "easeOut" as const }),
                delay: reduced ? 0 : i * 0.08,
              }}
              className="min-w-0 md:border-l md:border-border md:pl-8 md:first:border-l-0 md:first:pl-0"
            >
              <div className="flex items-baseline gap-3">
                <span
                  aria-hidden="true"
                  className="font-display text-h2 font-bold text-primary tabular-nums shrink-0"
                >
                  {i + 1}
                </span>
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
              </div>
              <p className="mt-3 pl-0 text-body text-pretty text-muted-foreground md:pl-[calc(theme-spacing*0)]">
                {step.text}
              </p>
            </m.li>
          ))}
        </ol>
      </div>
    </section>
  );
}

