import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";

// How it works: a dense band after the airy hero — the steps as rows of a price-list-like
// ledger under a heavy rule: step number and title on one line at the left, the description
// set at the right edge, each row separated by a hairline; stacked on phone.
type Step = {
  title: string;
  text: string;
};

export type HowItWorksProps = {
  heading: string;
  steps: Step[];
};

export default function HowItWorks({ heading, steps }: HowItWorksProps) {
  const reduced = useReducedMotion();
  const rise = (i: number) =>
    reduced
      ? {}
      : {
          initial: { opacity: 0, y: 16 },
          whileInView: { opacity: 1, y: 0 },
          viewport: { once: true, amount: 0.3 },
          transition: { duration: 0.5, ease: "easeOut" as const, delay: i * 0.08 },
        };

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-muted font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <h2 className="max-w-text font-display text-h1 font-bold text-balance wrap-break-word">{heading}</h2>
          <ol className="mt-10 border-t-2 border-foreground">
            {steps.map((step, i) => (
              <m.li
                key={step.title}
                {...rise(i)}
                className="grid gap-x-10 gap-y-3 border-b border-border py-7 md:grid-cols-12 md:items-baseline md:py-9"
              >
                <div className="flex min-w-0 items-baseline gap-4 md:col-span-6">
                  <span
                    aria-hidden="true"
                    className="shrink-0 font-display text-h2 font-bold text-primary tabular-nums"
                  >
                    {i + 1}
                  </span>
                  <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{step.title}</h3>
                </div>
                <p
                  className="pl-10 text-body text-pretty text-muted-foreground md:col-span-6 md:pl-0 md:text-lead"
                >
                  {step.text}
                </p>
              </m.li>
            ))}
          </ol>
        </div>
      </section>
    </LazyMotion>
  );
}
